  "inlineSchema": "// prisma/schema.prisma\n// Learn more: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\nmodel Package {\n  id              Int           @id @default(autoincrement())\n  title           String\n  description     String?\n  priceUSD        Int?\n  features        String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n  active          Boolean       @default(true)\n  audience        Audience      @default(INDIVIDUAL)\n  durationMin     Int?\n  image           String?\n  isPopular       Boolean       @default(false)\n  priceType       PriceType     @default(BUNDLE)\n  sessionsPerPack Int?\n  sortOrder       Int           @default(0)\n  startingAtUSD   Int?\n  userPackages    UserPackage[]\n}\n\nmodel User {\n  id                    Int                    @id @default(autoincrement())\n  email                 String                 @unique\n  name                  String?\n  hashedPassword        String\n  role                  String                 @default(\"learner\")\n  createdAt             DateTime               @default(now())\n  updatedAt             DateTime               @updatedAt\n  timezone              String?\n  isDisabled            Boolean                @default(false)\n  rateHourlyCents       Int?\n  ratePerSessionCents   Int?\n  assessmentSubmissions AssessmentSubmission[]\n  audits                Audit[]                @relation(\"Audit_actor\")\n  onboardingForms       OnboardingForm[]\n  teachingSessions      Session[]              @relation(\"SessionTeacher\")\n\n  // Legacy 1:1 learner ownership (Session.userId)\n  sessions Session[]\n\n  // New: membership rows for group sessions (and future-proof for 1:1 as well)\n  sessionParticipants SessionParticipant[]\n\n  sessionFeedbacks SessionFeedback[]\n  userPackages     UserPackage[]\n\n  // In-app notifications\n  notifications Notification[]\n\n  @@index([role])\n}\n\nmodel Notification {\n  id     Int  @id @default(autoincrement())\n  userId Int\n  user   User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // e.g. booking_confirmed, reminder_24h, payment_receipt\n  type String\n\n  title String\n  body  String?\n  data  Json?\n\n  readAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([userId, createdAt])\n  @@index([userId, readAt])\n}\n\nmodel Audit {\n  id        Int      @id @default(autoincrement())\n  actorId   Int\n  action    String\n  entity    String\n  entityId  Int?\n  meta      Json?\n  createdAt DateTime @default(now())\n  actor     User     @relation(\"Audit_actor\", fields: [actorId], references: [id])\n\n  @@index([entity, entityId])\n}\n\nmodel Session {\n  id      Int       @id @default(autoincrement())\n  title   String\n  startAt DateTime\n  endAt   DateTime?\n  notes   String?\n\n  // New: session kind + group capacity\n  type     SessionType @default(ONE_ON_ONE)\n  capacity Int?\n\n  // Legacy 1:1 learner owner (kept for compatibility + migration)\n  // For GROUP sessions, this can be null.\n  userId Int?\n  user   User? @relation(fields: [userId], references: [id])\n\n  teacherId Int?\n  teacher   User? @relation(\"SessionTeacher\", fields: [teacherId], references: [id])\n\n  // New: participant membership (many learners per session)\n  participants SessionParticipant[]\n\n  createdAt                       DateTime      @default(now())\n  updatedAt                       DateTime      @updatedAt\n  reminder24hSentAt               DateTime?\n  reminder6hSentAt                DateTime?\n  reminder1hSentAt                DateTime?\n  feedbackScore                   Int?\n  status                          SessionStatus @default(scheduled)\n  joinUrl                         String?\n  teacherFeedbackComments         String?\n  teacherFeedbackFutureSteps      String?\n  teacherFeedbackMessageToLearner String?\n  classroomState                  Json?\n\n  feedback SessionFeedback?\n\n  @@index([userId, startAt])\n  @@index([teacherId, startAt])\n  @@index([type, startAt])\n}\n\nmodel SessionParticipant {\n  id Int @id @default(autoincrement())\n\n  sessionId Int\n  session   Session @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  userId Int\n  user   User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  status     String    @default(\"booked\")\n  attendedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([sessionId, userId])\n  @@index([userId])\n  @@index([sessionId])\n}\n\nmodel SessionFeedback {\n  id                String   @id @default(cuid())\n  sessionId         Int      @unique\n  createdAt         DateTime @default(now())\n  commentsOnSession String?\n  futureSteps       String?\n  messageToLearner  String?\n  teacherId         Int\n  updatedAt         DateTime @updatedAt\n  session           Session  @relation(fields: [sessionId], references: [id])\n  teacher           User     @relation(fields: [teacherId], references: [id])\n}\n\nmodel VerificationCode {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  codeHash  String\n  expiresAt DateTime\n  attempts  Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel PasswordResetCode {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  codeHash  String\n  expiresAt DateTime\n  attempts  Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Order {\n  id            String   @id\n  amountCents   Int\n  currency      String   @default(\"EGP\")\n  status        String   @default(\"pending\")\n  psp           String   @default(\"paymob\")\n  pspOrderId    Int?\n  customerEmail String?\n  customerPhone String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n  userId        Int?\n  packageId     Int?\n  paymobTxnId   Int?\n\n  userPackage UserPackage? // ✅ add this line (back relation)\n\n  @@index([userId])\n  @@index([packageId])\n}\n\nmodel UserPackage {\n  id        Int @id @default(autoincrement())\n  userId    Int\n  packageId Int\n\n  // ✅ NEW: ties the entitlement to a specific Order.id (merchant_order_id)\n  orderId String? @unique\n  order   Order?  @relation(fields: [orderId], references: [id])\n\n  title             String\n  minutesPerSession Int?\n  sessionsTotal     Int\n  sessionsUsed      Int       @default(0)\n  expiresAt         DateTime?\n  status            String    @default(\"active\")\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @default(now()) @updatedAt\n  user              User      @relation(fields: [userId], references: [id])\n  package           Package   @relation(fields: [packageId], references: [id])\n\n  @@index([userId, status])\n}\n\nmodel OnboardingForm {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  packageId Int?\n  answers   Json\n  status    String   @default(\"submitted\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  user      User     @relation(fields: [userId], references: [id])\n\n  @@index([userId, createdAt])\n}\n\nmodel AssessmentSubmission {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  packageId Int?\n  text      String\n  wordCount Int\n  status    String   @default(\"submitted\")\n  score     Int?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  user      User     @relation(fields: [userId], references: [id])\n\n  @@index([userId, createdAt])\n}\n\nenum Audience {\n  INDIVIDUAL\n  CORPORATE\n}\n\nenum PriceType {\n  PER_SESSION\n  BUNDLE\n  CUSTOM\n}\n\nenum SessionType {\n  ONE_ON_ONE\n  GROUP\n}\n\nenum SessionStatus {\n  scheduled\n  completed\n  canceled\n}\n",
